import { MeshStandardNodeMaterial, PlaneGeometry, Group, Mesh, Color } from 'three/webgpu';
import { uv, vec2, vec3, mix, smoothstep, texture, uniform } from 'three/tsl';
import { gsap } from 'gsap';

export function createNode(config, ctx) {
  const { Group: ThreeGroup, Mesh: ThreeMesh, PlaneGeometry: ThreePlaneGeometry } = ctx.THREE;

  const root = new ThreeGroup();

  // Create local timelines to keep track of
  const activeTimelines = [];

  // Parse colors
  const colors = config.intent?.visualSpec?.colors || {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10'
  };

  // 1. BACKING PLATE (Machined Metal Button Deck)
  // Dimensions for high-end horizontal CTA
  const plateWidth = 2.4;
  const plateHeight = 0.65;
  const plateGeo = new ThreePlaneGeometry(plateWidth, plateHeight, 1, 1);

  // Load backing texture
  const metalMaterial = new MeshStandardNodeMaterial({
    roughness: 0.55,
    metalness: 0.5,
    transparent: true,
    opacity: 0.95
  });

  const plate = new ThreeMesh(plateGeo, metalMaterial);
  root.add(plate);

  ctx.textureLoader.loadTexture(config.imageUrl || '/prism-assets/chrome/brushed-metal.map.png').then((tex) => {
    tex.wrapS = 1000; // Repeat
    tex.wrapT = 1000;

    // TSL Shader logic: Mix the brushed metal texture with an engineered gradient
    const uvCoords = uv();
    const gradVal = uvCoords.y; // simple linear vertical gradient
    const baseColor = vec3(new Color(colors.surface));
    const paperColor = vec3(new Color(colors.paper));

    // Smooth transition from surface near-black to a soft gradient
    const mixedBg = mix(baseColor, paperColor.mul(0.12), gradVal);

    // Mix with texture map
    const texColor = texture(tex, uvCoords.mul(1.5));
    const finalDiffuse = mix(mixedBg, texColor.rgb.mul(0.4), 0.5);

    metalMaterial.colorNode = finalDiffuse;
    metalMaterial.needsUpdate = true;
  });

  // 2. ACCENT BORDER (Signal Red #ff2a38)
  // Left border notch or subtle signal accent
  const accentWidth = 0.04;
  const accentHeight = plateHeight;
  const accentGeo = new ThreePlaneGeometry(accentWidth, accentHeight);
  const accentMat = new MeshStandardNodeMaterial({
    color: colors.accent,
    emissive: colors.accent,
    emissiveIntensity: 1.2
  });
  const accentLine = new ThreeMesh(accentGeo, accentMat);
  accentLine.position.set(-plateWidth / 2 + accentWidth / 2, 0, 0.01);
  root.add(accentLine);

  // 3. TYPOGRAPHY / TEXT
  const textItems = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const mainTextVal = textItems[0]?.text ?? "Get started";

  // Create MSDF text via atlas
  const textObj = ctx.fontAtlas.createText(mainTextVal, {
    fontSize: 28, // Scaled down for button ratio inside local frame
    color: colors.paper,
    align: 'center'
  });

  // Center-right positioning relative to accent line
  textObj.position.set(0.04, -0.05, 0.02);
  root.add(textObj);

  // Apply Cinematic Primitives if available (optional safeguard)
  if (config.cinematicPrimitives) {
    for (const primitive of config.cinematicPrimitives) {
      if (ctx.primitives[primitive.name]) {
        const pInstance = ctx.primitives[primitive.name](root, primitive.params);
        if (pInstance) {
          activeTimelines.push(pInstance);
        }
      }
    }
  }

  // Define cleanup routine
  root.userData.cleanup = function() {
    activeTimelines.forEach((tl) => {
      if (tl.timeline) tl.timeline.kill();
      if (tl.cleanup) tl.cleanup();
    });
    plateGeo.dispose();
    metalMaterial.dispose();
    accentGeo.dispose();
    accentMat.dispose();
  };

  return root;
}
